def collapse_duplicate_approved_submissions(apps, schema_editor):
    Submission = apps.get_model("collector", "Submission")
    class_ids = (
        Submission.objects.filter(status="approved")
        .values_list("class_group_id", flat=True)
        .distinct()
    )
    for class_id in class_ids:
        approved = list(
            Submission.objects.filter(class_group_id=class_id, status="approved")
            .order_by("-submitted_at", "-id")
        )
        for duplicate in approved[1:]:
            duplicate.status = "rejected"
            duplicate.save(update_fields=["status"])


